package app.focal.core

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/**
 * Reproduces every expected field of `transcript-vectors.json`, generated by the Python reference
 * implementation of the speech experiments (with their audit corrections and the rebuild decisions).
 */
class TranscriptVectorsTest {
    private val vectors = MiniJson.parse(
        checkNotNull(javaClass.getResource("/transcript-vectors.json")).readText(),
    ).obj()
    private val constants = vectors["constants"].obj()
    private val format = FormatConfig(
        seamPauseMs = constants["T_SEAM_MS"].long(),
        paragraphPauseMs = constants["T_PARA_MS"].long(),
        longPauseMs = constants["LONG_PAUSE_MS"].long(),
        minSentences = constants["MIN_SENTENCES"].long().toInt(),
        maxWords = constants["MAX_WORDS"].long().toInt(),
        dedupeMs = constants["DEDUPE_MS"].long(),
        minWordEndMs = constants["MIN_WORD_END_MS"].long(),
    )

    @Test
    fun constantsMatchTheShippedTuning() {
        assertEquals(FormatConfig(), format)
        assertEquals(SpeechTuning.TITLE_MAX_CHARS, constants["TITLE_MAX"].long().toInt())
        assertEquals(SpeechTuning.TITLE_MIN_CHARS, constants["MIN_TITLE_CHARS"].long().toInt())
        assertEquals(SpeechTuning.DOUBT_THRESHOLD, constants["FLAG_THRESHOLD"].double())
        val seg = constants["segmenter"].obj()
        assertEquals(SegmenterConfig(), segmenterConfig(seg))
    }

    @Test
    fun formatCases() {
        val cases = vectors["format_cases"].list()
        assertEquals(80, cases.size)
        for (c in cases.map { it.obj() }) {
            val id = c["id"] as String
            assertTrue(c["options"].obj().isEmpty(), id)
            val windows = c["input"].obj()["windows"].list().map(::window)
            val expected = c["expected"].obj()
            val result = Formatter.format(windows, format)

            assertEquals(expected["raw_texts"].list(), result.rawWords.map { it.text }, "$id raw")
            val words = expected["words"].list().map { it.obj() }
            assertEquals(words.size, result.words.size, "$id word count")
            words.zip(result.words).forEachIndexed { i, (e, w) ->
                assertEquals(e["text"], w.text, "$id word $i")
                assertEquals(e["start_ms"].long(), w.startMs, "$id word $i start")
                assertEquals(e["end_ms"].long(), w.endMs, "$id word $i end")
                assertEquals(e["punct_only"], w.punctOnly, "$id word $i punct")
                assertEquals(e["window"].long().toInt(), w.window, "$id word $i window")
                assertEquals(e["unknown_piece"], w.unknownPiece, "$id word $i unknown")
                val conf = e["conf_min"].doubleOrNull()
                if (conf == null) assertNull(w.confidence, "$id word $i conf")
                else assertEquals(conf, assertNotNull(w.confidence, "$id word $i conf"), 1e-6, "$id word $i conf")
            }
            val ops = expected["seam_ops"].list().map { it.obj() }.map {
                val removed = it["period_removed"].list()
                SeamOp(it["after_word"].long().toInt(), it["next_word"].long().toInt(), removed[0] as String, removed[1] as String)
            }
            assertEquals(ops, result.seamOps, "$id seams")
            val paragraphs = expected["paragraphs"].list().map { p -> p.list().let { it[0].long().toInt() until it[1].long().toInt() } }
            assertEquals(paragraphs, result.paragraphs, "$id paragraphs")
            assertEquals(expected["title"], result.title, "$id title")
            assertEquals(
                expected["flagged_word_indices"].list().map { it.long().toInt() },
                Doubt.flagged(result.words, enabled = true, threshold = constants["FLAG_THRESHOLD"].double()),
                "$id flags",
            )
            assertEquals(expected["copy_text"], result.copyText, "$id copy")
            assertIncrementalMatches(id, windows, result)
        }
    }

    /** The worker's window-by-window assembly, restored from storage after every window, equals the batch. */
    private fun assertIncrementalMatches(id: String, windows: List<DecodedWindow>, batch: FormattedTranscript) {
        val closed = ArrayList<List<Word>>()
        var open = emptyList<Word>()
        windows.forEachIndexed { index, window ->
            val update = TranscriptAssembler(format, open).append(window, index)
            if (update.paragraphs.isEmpty()) return@forEachIndexed
            closed += update.paragraphs.dropLast(1)
            open = update.paragraphs.last()
        }
        val all = if (open.isEmpty()) closed else closed + listOf(open)
        assertEquals(batch.paragraphs.map { r -> r.map { batch.words[it] } }, all, "$id incremental")
    }

    @Test
    fun segmenterCases() {
        val cases = vectors["segmenter_cases"].list()
        assertEquals(17, cases.size)
        for (c in cases.map { it.obj() }) {
            val id = c["id"] as String
            val input = c["input"].obj()
            val total = input["total_ms"].long()
            val quiet = ArrayList<Boolean>()
            val peaks = ArrayList<Int>()
            val energies = ArrayList<Long>()
            for (s in input["segments"].list().map { it.obj() }) {
                val ms = s["ms"].long().toInt()
                repeat(ms / 10) { quiet += s["quiet"] as Boolean; peaks += s["peak"].long().toInt() }
                repeat(ms / 20) { energies += s["energy"].long() }
            }
            val planner = CutPlanner(segmenterConfig(input), SegmenterStart.BEGINNING, 0, 0)
            val out = ArrayList<WindowPlan>()
            var frame = 0
            var slot = 0
            fun feedSlots(until: Int) {
                while (slot < until) {
                    while (frame < energies.size && frame <= slot / 2) planner.addFrame(energies[frame++])
                    planner.addSlot(quiet[slot], peaks[slot])
                    slot++
                }
                out += planner.takeReady()
            }
            for (b in input["breaks_ms"].list().map { it.long() }) {
                feedSlots((b / 10).toInt())
                planner.close(EndKind.BREAK, b, 0)
                out += planner.takeReady()
            }
            feedSlots(minOf(quiet.size.toLong(), total / 10).toInt())
            planner.close(EndKind.FINAL, total, 0)
            out += planner.takeReady()

            val expected = c["expected"].obj()["windows"].list().map { it.obj() }
            assertEquals(expected.size, out.size, "$id window count")
            expected.zip(out).forEachIndexed { i, (e, w) ->
                val actual = mapOf(
                    "own_start_ms" to w.ownStartMs, "own_end_ms" to w.ownEndMs,
                    "audio_start_ms" to w.audioStartMs, "audio_end_ms" to w.audioEndMs,
                    "keep_lo_ms" to w.keepLoMs, "keep_hi_ms" to w.keepHiMs,
                    "end_kind" to w.endKind.name.lowercase(), "decide_at_ms" to w.decideAtMs,
                    "speech_ms" to w.speechMs, "peak" to w.peak.toLong(),
                )
                assertEquals(e, actual, "$id window $i")
                assertEquals(i, w.index, "$id window $i index")
            }
        }
    }

    @Test
    fun vadHysteresisCases() {
        val cases = vectors["vad_hysteresis_cases"].list()
        assertEquals(6, cases.size)
        for (c in cases.map { it.obj() }) {
            val input = c["input"].obj()
            val vad = SileroHysteresis(
                threshold = input["threshold"].double().toFloat(),
                minSpeechSamples = input["min_speech_samples"].long().toInt(),
                minSilenceSamples = input["min_silence_samples"].long().toInt(),
                windowSamples = input["window"].long().toInt(),
            )
            val actual = input["probs"].list().map { vad.accept(it.double().toFloat()) }
            assertEquals(c["expected"].obj()["speech"].list(), actual, c["id"] as String)
        }
    }

    private fun segmenterConfig(m: Map<String, Any?>) = SegmenterConfig(
        minMs = m["min_ms"].long(),
        maxMs = m["max_ms"].long(),
        pauseMs = m["pause_ms"].long(),
        overlapMs = m["overlap_ms"].long(),
        hardCutMinRunMs = m["fallback_run_ms"].long(),
        rightContextMs = m["rctx_ms"].long(),
        pauseLeadInMs = m["pause_lead_in_ms"].long(),
    )

    private fun window(raw: Any?): DecodedWindow {
        val w = raw.obj()
        return DecodedWindow(
            audioStartMs = w["audio_start_ms"].long(),
            keepLoMs = w["keep_lo_ms"].longOrNull(),
            keepHiMs = w["keep_hi_ms"].longOrNull(),
            tokens = w["tokens"].list().map { it.obj() }.map {
                AsrToken(it["text"] as String, it["start_s"].double(), it["dur_s"].double(), it["logp"].doubleOrNull())
            },
        )
    }
}
